// Detail panel additions per Ortsbezirk — rent / complaints stay seeded; Kita is now real data joined below.
function generateDetailExtras(seed) {
  const base = (seed * 7919) % 1000;
  return {
    rent_eur_m2: (8.5 + (base % 80) / 10).toFixed(2),
    complaint_days: (3 + (base % 90) / 10).toFixed(1)
  };
}
const KITA_BY_NAME = Object.fromEntries(KITA_VERSORGUNG.ortsbezirke.map(o => [o.name, o]));
ORTSBEZIRKE.forEach((d, i) => {
  const extras = generateDetailExtras(parseInt(d.id) + i);
  d.rent = extras.rent_eur_m2;
  d.complaint_days = extras.complaint_days;
  const k = KITA_BY_NAME[d.name];
  if (k) {
    d.kita_u3   = k.u3;
    d.kita_elem = k.elem;
  }
});

